## rNumVec()
## ==========================================================================
test_that("rNumVec normal/uniform/poisson/negbin all return length L", {
  set.seed(1)
  expect_length(rNumVec("normal", L = 5, p1 = 10, p2 = 1), 5)
  expect_length(rNumVec("uniform", L = 5, p1 = 10, p2 = 1), 5)
  expect_length(rNumVec("poisson", L = 5, p1 = 3), 5)
  expect_length(rNumVec("negbin", L = 5, p1 = 0.5, p2 = 3), 5)
})

test_that("rNumVec poisson/negbin outputs are always in (0, 1]", {
  set.seed(2)
  x <- rNumVec("poisson", L = 200, p1 = 4)
  expect_true(all(x > 0 & x <= 1))
  y <- rNumVec("negbin", L = 200, p1 = 0.3, p2 = 4)
  expect_true(all(y > 0 & y <= 1))
})

test_that("rNumVec rejects unsupported distribution names", {
  expect_error(rNumVec("gamma", L = 1, p1 = 1, p2 = 1))
})

test_that("rNumVec uniform: the original asymmetric-skew case (p1 < p2) stays fixed", {
  set.seed(3)
  p1 <- 1; p2 <- 5
  draws <- rNumVec("uniform", L = 100000, p1 = p1, p2 = p2)
  expect_true(all(draws >= 0 & draws <= 1))
  expect_equal(mean(draws), 0.5, tolerance = 0.02)
})

test_that("rNumVec uniform: min can no longer end up above max", {
  p1 <- 5; p2 <- 1
  min_val <- max(0, min(1, p1 - p2))
  max_val <- min(1, p1 + p2)
  expect_true(min_val <= max_val)

  set.seed(14)
  draws <- rNumVec("uniform", L = 10000, p1 = p1, p2 = p2)
  expect_true(all(draws >= 0 & draws <= 1))
  expect_equal(draws, rep(1, 10000))
})

