test_that("tPn.r forces the valid flag TRUE on every transposon in a vector", {
  v <- c(mk_tpn("gG1", 1, 0, valid = FALSE), mk_tpn("iG2", 2, 0, valid = FALSE))
  out <- tPn.r(v)
  expect_length(out, 2)
  parsed <- lapply(out, tPn.io)
