test_that("tPn.reloc shifts downstream genes' start/end by the transposon size", {
  gdf <- mk_gene_df(c("g1", "g2", "g3"), start = c(1, 100, 200), end = c(50, 150, 250))
  out <- tPn.reloc(mk_tpn("", 0, 0, size = 30), gen = 1, gene.df = gdf, tPn.prob = 0.01)
  expect_true(all(out$end >= gdf$end))
})

test_that("tPn.reloc correctly leaves the start unshifted for a non-last gene's CDS insertion", {
  gdf <- mk_gene_df(c("g1", "g2"), start = c(1, 500), end = c(100, 600))
  before_start <- gdf$start[1]
  out <- tPn.reloc(mk_tpn("", 0, 0, size = 40), gen = 1, gene.df = gdf, tPn.prob = 0.05)
  expect_equal(out$start[1], before_start)
  expect_equal(out$end[1] - out$start[1] + 1, out$length[1])
})

